mapper.select:
select CHECK_SEQNO checkSeqno, REP_CODE repCode, REP_NAME repName, VALID_KEY validKey, CHECK_RESULT checkResult, ERROR_INFO errorInfo, WARN_INFO warnInfo, DATE_FORMAT(DATA_TIME,'%Y-%m-%d') checkTime from CHB_REPORT_CHECK
CHECK_RESULT !='01'
and DATE_FORMAT(DATA_TIME,'%Y-%m-%d') >= #{updateTimeStart,jdbcType=VARCHAR}
and DATE_FORMAT(DATA_TIME,'%Y-%m-%d') <= #{updateTimeEnd,jdbcType=VARCHAR}
and CHECK_RESULT = #{checkResult,jdbcType=VARCHAR}
